/// The two network tools, and the shared HTTP plumbing they need.
///
/// GENERATED by the split of `tools.zig`, then edited by hand. It lives in
/// its own file so it can be tested on its own, without the TUI.
const std = @import("std");
const dispatch = @import("dispatch.zig");
const common = @import("common.zig");
const http = @import("../lib/http_client.zig");
const web = @import("../lib/web.zig");
const webcache = @import("../lib/webcache.zig");
const agent = @import("../agent.zig");

/// The page cache, and the lock around it.
///
/// `web_fetch` is on the parallel-safe list, so three of them can run at once
/// and this is shared mutable state. It is a `std.atomic.Mutex` and NOT
/// `std.Thread.Mutex` (which does not exist in 0.16), and the critical section
/// is a map lookup: it holds for microseconds and never spans I/O.
///
/// The arena is never freed while the process runs (see `Model.deinit`): a map
/// that several threads can read is not freed at runtime, only at teardown.
var pages: webcache.Cache = .{ .gpa = std.heap.page_allocator };
var pages_lock: std.atomic.Mutex = .unlocked;

/// Takes the lock, yielding while somebody else has it.
///
/// `std.atomic.Mutex` is a spinlock in this Zig: `tryLock`/`unlock` and no
/// `lock()`. A plain spin would be rude here because three `web_fetch` calls can
/// land at once and each holds the lock for a map lookup, so the wait is short
/// but real.
fn lockPages() void {
    while (!pages_lock.tryLock()) std.Thread.yield() catch {};
}

/// Drops every cached page. `/clean` calls it so a cache in memory is not the
/// last thing left behind, and the tests call it so one does not see another's.
pub fn clearFetchCache() void {
    lockPages();
    defer pages_lock.unlock();
    pages.deinit();
    pages = webcache.Cache.init(std.heap.page_allocator);
}

fn nowMs(io: std.Io) i64 {
    return @intCast(@divTrunc(std.Io.Timestamp.now(io, .real).nanoseconds, std.time.ns_per_ms));
}

/// Hard cap on a web response. 200 KB of text is plenty to read a doc and
/// keeps an endless page (a listing of 50 000 links) from blowing up the turn's
/// context.
pub const web_hard_cap = 200 * 1024;

/// `web_fetch`: GET a URL and return the content as readable text.
///
/// The body ALWAYS goes through `web.htmlToText` when it looks like HTML, because
/// spending context on 300 KB of tags is throwing it away. JSON or plain text
/// pass through untouched.
pub fn toolWebFetch(io: std.Io, obj: std.json.ObjectMap, arena: std.mem.Allocator) ![]const u8 {
    const url = common.getStr(obj, "url") orelse
        return "error: web_fetch needs a `url` (http:// or https://)";
    const trimmed = std.mem.trim(u8, url, " \t\r\n");
    if (!isHttpUrl(trimmed)) {
        return std.fmt.allocPrint(arena, "error: only http:// and https:// URLs can be fetched, got: {s}", .{trimmed});
    }

    // The credential endpoints, before anything else happens.
    //
    // `web_fetch` asks for NO permission (see `needsPermission`) while `bash` does, so
    // this is the one door into the machine that the user never opens. That makes it a
    // permission question, not a sandbox question: a model can always reach the same
    // address with `curl` through `bash`, behind a dialog. What this removes is the case
    // where a page the model READ tells it to fetch an internal address and the answer
    // lands in the context and on the user's screen with nobody asked.
    if (web.isCredentialEndpoint(trimmed)) {
        return std.fmt.allocPrint(
            arena,
            "refused: {s} is a cloud instance-metadata endpoint, which serves credentials (AWS, GCP, Azure and DigitalOcean all use link-local for it). " ++
                "Fetching it would put a key in the transcript. " ++
                "If you genuinely need a private address, ZODE_WEB_ALLOW_LOCAL=1 allows the private ranges " ++
                "-- and `bash` with `curl` reaches it behind a permission dialog either way.",
            .{web.urlHost(trimmed)},
        );
    }
    if (web.isPrivateHost(trimmed) and !allowLocal()) {
        return std.fmt.allocPrint(
            arena,
            "refused: {s} is a loopback or private address, and `web_fetch` asks for no permission, so reaching it would be the one thing on this machine that never got your say. " ++
                "Set ZODE_WEB_ALLOW_LOCAL=1 if that is what you want (fetching your own dev server is a normal thing to do), or use `bash` with curl, which does ask.",
            .{web.urlHost(trimmed)},
        );
    }

    var max_bytes: usize = common.max_tool_output;
    if (common.getInt(obj, "max_bytes")) |mb| {
        if (mb > 0) max_bytes = @min(@as(usize, @intCast(mb)), web_hard_cap);
    }
    // Where this window starts, in bytes of the EXTRACTED text (after HTML is
    // stripped): the model sees the note's byte positions, so the offset it is
    // told to pass and the offset it passes are counted from the same string.
    var offset: usize = 0;
    if (common.getInt(obj, "offset")) |o| {
        if (o > 0) offset = @intCast(o);
    }

    // The page comes out of the cache BEFORE the window is applied, which is
    // the whole point: `offset` is a window into the extracted text, so the
    // second and third windows of a long document used to re-download and
    // re-strip the whole page each time.
    if (cachedText(trimmed, nowMs(io))) |page_text| {
        return web.excerpt(arena, page_text, offset, max_bytes);
    }

    const got = try fetchPage(io, arena, trimmed);
    switch (got) {
        // A redirect that leaves the site is a DECISION, not a hop: the URL it
        // names is a host the user never agreed to, and the page that redirected
        // there is untrusted text that chose the address. So the tool reports
        // it and the model asks again, and everything said about this host
        // (and any allowlist entry for it) applies to the NEW one.
        .other_site => |info| return std.fmt.allocPrint(
            arena,
            "redirect: {s} redirects to a DIFFERENT host, and this tool does not follow it on its own.\n" ++
                "  from: {s}\n  to:   {s}  (HTTP {d})\n" ++
                "Fetch that URL yourself if you want it: it is a different site, so anything you have allowed for {s} does not cover it.",
            .{ web.urlHost(trimmed), trimmed, info.to, info.status, web.urlHost(trimmed) },
        ),
        .text => |t| {
            storeText(trimmed, t, nowMs(io));
            // CAREFUL: the result is COPIED into memory owned by the arena.
            // Returning a slice of the HTTP buffer is a time bomb: the
            // `defer freeBody` releases it when this function returns and the
            // ArenaAllocator REUSES that memory on the next allocation. The
            // caller read `0xAA` where the text should have been.
            return web.excerpt(arena, t, offset, max_bytes);
        },
        // A 4xx/5xx, a compressed body or a transport failure. All three are
        // answers the model can act on, and none of them is cached: the point
        // of the cache is to make a REPEAT cheap, and nobody repeats a 403 on
        // purpose.
        .text_out => |m| return m,
    }
}

const Fetched = union(enum) {
    /// The extracted text of the page.
    text: []const u8,
    /// The URL points somewhere else, and the tool did not go.
    other_site: struct { to: []const u8, status: u16 },
    /// Something to say instead: a status, a refusal, a transport error.
    text_out: []const u8,
};

/// GET `url`, following the redirects that stay on the same site.
fn fetchPage(io: std.Io, arena: std.mem.Allocator, url: []const u8) !Fetched {
    var url_buf: [web.max_url_len + 16]u8 = undefined;
    @memcpy(url_buf[0..url.len], url);
    var current: []const u8 = url_buf[0..url.len];

    var h = http.Http.init(arena, io);
    defer h.deinit();

    var hops: usize = 0;
    while (hops <= web.max_redirects) {
        // `http://` is upgraded once, here, and a failure to do it is not an
        // error: it means the URL was already https.
        _ = web.upgradeHttps(current, url_buf[0..]);

        var loc_buf: [web.max_url_len]u8 = undefined;
        const res = h.getInspect(current, &browserHeaders(), &loc_buf) catch |err| {
            return .{ .text_out = std.fmt.allocPrint(arena, "error fetching {s}: {t}", .{ current, err }) catch "error: the request failed" };
        };
        defer h.freeBody(res.body);

        if (res.status >= 300 and res.status < 400) {
            hops += 1;
            const location = res.location orelse {
                return .{ .text_out = std.fmt.allocPrint(arena, "HTTP {d}: {s} redirected without a `location` to follow.", .{ res.status, current }) catch "the server sent a redirect with no target" };
            };
            var next_buf: [web.max_url_len]u8 = undefined;
            const next = web.resolveLocation(current, location, &next_buf) orelse {
                return .{ .text_out = std.fmt.allocPrint(arena, "HTTP {d}: {s} redirects to \"{s}\", which is not an http(s) URL.", .{ res.status, current, location }) catch "the redirect target is not a page" };
            };
            if (!web.sameSite(current, next)) {
                return .{ .other_site = .{ .to = try arena.dupe(u8, next), .status = res.status } };
            }
            @memcpy(url_buf[0..next.len], next);
            current = url_buf[0..next.len];
            continue;
        }

        const body = res.body;
        // A compressed body is not text: saying so is infinitely better than
        // returning binary and letting the model read it as if it were words.
        if (looksCompressed(body)) |kind| {
            return .{ .text_out = std.fmt.allocPrint(arena, "{s} answered with {s}-encoded content that zode cannot decode. Try a different URL (a .json or .txt endpoint usually works).", .{ current, kind }) catch "the body came compressed" };
        }
        // A 4xx/5xx is information too: return the status and whatever the
        // server said, which is where the real reason is.
        if (res.status < 200 or res.status >= 300) {
            return .{ .text_out = std.fmt.allocPrint(arena, "HTTP {d} {s}\n{s}", .{
                res.status,
                current,
                body[0..@min(body.len, 2000)],
            }) catch "the server refused" };
        }

        const is_html = looksLikeHtml(body);
        const text = if (is_html) web.htmlToText(arena, body) else body;
        if (text.len == 0) return .{ .text_out = "(empty body)" };
        return .{ .text = text };
    }

    return .{ .text_out = std.fmt.allocPrint(arena, "{s} redirected more than {d} times and stopped being a page.", .{ url, web.max_redirects }) catch "too many redirects" };
}

fn cachedText(url: []const u8, now: i64) ?[]const u8 {
    lockPages();
    defer pages_lock.unlock();
    return pages.get(url, now);
}

fn storeText(url: []const u8, text: []const u8, now: i64) void {
    lockPages();
    defer pages_lock.unlock();
    pages.put(url, text, now);
}

/// `web_search`: real search results, with two engines behind one contract.
///
/// The default is DuckDuckGo (`html/` → `lite/`, a scrape, no key). With
/// `ZODE_BRAVE_KEY` set the real index answers first and the free chain is the
/// fallback. Whichever answers, the model gets the same numbered list — it does
/// not have to know which engine it was.
///
/// The scrape will break the day they change one of the HTML classes. When that
/// happens, the error says so (with the alternative) instead of returning an
/// empty list, which the model would interpret as "there are no results".
pub fn toolWebSearch(io: std.Io, obj: std.json.ObjectMap, arena: std.mem.Allocator) ![]const u8 {
    const query = common.getStr(obj, "query") orelse
        return "error: web_search needs a `query`";
    const q = std.mem.trim(u8, query, " \t\r\n");
    if (q.len == 0) return "error: empty query";

    var max_results: usize = 5;
    if (common.getInt(obj, "max_results")) |mr| {
        if (mr > 0) max_results = @min(@as(usize, @intCast(mr)), 20);
    }

    var allowed = std.ArrayList([]const u8).empty;
    defer allowed.deinit(arena);
    var blocked = std.ArrayList([]const u8).empty;
    defer blocked.deinit(arena);
    readDomains(obj, "allowed_domains", arena, &allowed) catch {};
    readDomains(obj, "blocked_domains", arena, &blocked) catch {};
    const wants_filter = allowed.items.len > 0 or blocked.items.len > 0;

    // A real index when the user has one: `ZODE_BRAVE_KEY` turns it on, and the
    // free DuckDuckGo chain stays both the default (a tool that needs a signup to
    // work at all does not work) and the fallback (a configured-but-broken key
    // must not break a tool that otherwise works). When Brave fails its reason
    // rides in front of whatever the free chain answers, so a wrong key is
    // visible exactly while it is wrong and never once it works.
    var engine_note: []const u8 = "";
    // Empty and NOT `undefined`: with no Brave key the branch below never runs,
    // and reading `.len` off `undefined` is reading garbage — it overflowed an
    // integer in the live search test.
    var results: []const u8 = "";
    if (braveKey()) |key| {
        switch (braveSearch(io, arena, key, q, max_results)) {
            .done => |r| results = r,
            .fell_back => |why| engine_note = why,
        }
    }
    if (results.len == 0) results = freeChain(io, arena, q, max_results);

    if (wants_filter) {
        const kept = web.filterByDomain(arena, results, allowed.items, blocked.items);
        if (kept.len == 0) {
            // "Nothing after filtering" is not "nothing on the internet". A model
            // that reads the first one tells the user the topic has no pages at
            // all, which is the one answer a search must never give.
            return std.fmt.allocPrint(
                arena,
                "{d} result(s) for \"{s}\", and none of them is on the {s} domain(s). That is what the filter found, NOT that there is nothing about this: try another site or a broader query.",
                .{ max_results, q, domainPhrase(allowed.items, blocked.items) },
            ) catch "no result passed the domain filter";
        }
        results = kept;
    }

    const noted = withNote(arena, engine_note, results);
    return std.fmt.allocPrint(arena, "{s}{s}", .{ noted, citeReminder }) catch noted;
}

/// One line, and it is the only instruction the model gets about sources.
///
/// A search result is a claim's evidence; without this the model answers from a
/// snippet it half-read and the user has no way back to where it came from. It
/// rides at the END, after the note about a broken key, because it is the last
/// thing read and the last thing read is what a model is most likely to do.
const citeReminder =
    "\nCite the URL of every source you used, as a markdown link next to the claim it supports. " ++
    "Do not cite a result you did not open.\n";

/// `Domains foo.com, bar.com.` — used only in the "nothing passed" message, so
/// it names what was filtered instead of leaving the model to guess.
fn domainPhrase(allowed: []const []const u8, blocked: []const []const u8) []const u8 {
    if (allowed.len > 0 and blocked.len > 0) return "allowed or blocked";
    if (allowed.len > 0) return "allowed";
    return "blocked";
}

/// Reads a `["a", "b"]` of domains out of the arguments.
fn readDomains(
    obj: std.json.ObjectMap,
    key: []const u8,
    arena: std.mem.Allocator,
    out: *std.ArrayList([]const u8),
) !void {
    const v = obj.get(key) orelse return;
    if (v != .array) return;
    for (v.array.items) |item| {
        if (item != .string) continue;
        const d = std.mem.trim(u8, item.string, " \t\r\n");
        if (d.len == 0) continue;
        try out.append(arena, d);
    }
}

/// The key that turns on Brave's real index, when the user has one.
fn braveKey() ?[]const u8 {
    const v = agent.environ_global orelse return null;
    const k = v.get("ZODE_BRAVE_KEY") orelse return null;
    return if (k.len == 0) null else k;
}

/// One Brave attempt, and what it means for the rest of the search.
const BraveOutcome = union(enum) {
    /// Brave answered: the search is over (the list, or an honest "nothing
    /// there" from a real index).
    done: []const u8,
    /// Brave could not answer, and this is why. The free chain runs; if THAT
    /// fails too, the message carries both reasons.
    fell_back: []const u8,
};

/// `GET https://api.search.brave.com/res/v1/web/search?q=…&count=…`, the same
/// call Brave's reference clients make (their Python client sends these two as
/// query params with the `X-Subscription-Token` header).
///
/// Only `q` and `count` are sent: every optional parameter whose type has not
/// been verified costs a 422 on every search, and `description` comes back with
/// `<strong>` highlight marks either way — the parser strips them, so no
/// parameter is needed for cleanliness either.
fn braveSearch(io: std.Io, arena: std.mem.Allocator, key: []const u8, q: []const u8, max_results: usize) BraveOutcome {
    var url_buf: [1024]u8 = undefined;
    var uw: std.Io.Writer = .fixed(&url_buf);
    uw.writeAll("https://api.search.brave.com/res/v1/web/search?q=") catch return .{ .fell_back = "the search API (ZODE_BRAVE_KEY): query too long" };
    percentEncodeQuery(q, &uw) catch return .{ .fell_back = "the search API (ZODE_BRAVE_KEY): query too long" };
    // `count` is an integer 1..20 in Brave's own request model.
    uw.print("&count={d}", .{@min(@max(max_results, 1), 20)}) catch return .{ .fell_back = "the search API (ZODE_BRAVE_KEY): query too long" };
    const url = uw.buffered();

    var h = http.Http.init(arena, io);
    defer h.deinit();

    const res = h.getWithHeaders(url, &braveHeaders(key)) catch |err| {
        return .{ .fell_back = std.fmt.allocPrint(
            arena,
            "the search API (ZODE_BRAVE_KEY) could not be reached: {t}",
            .{err},
        ) catch "the search API (ZODE_BRAVE_KEY) could not be reached" };
    };
    defer h.freeBody(res.body);

    if (res.status < 200 or res.status >= 300) {
        // The error envelope carries the real reason
        // ("SUBSCRIPTION_TOKEN_INVALID: The provided subscription token is
        // invalid."); a bare HTTP 422 sends the user to debug the wrong thing.
        var detail: []const u8 = "";
        switch (web.braveResults(arena, res.body, 1)) {
            .unusable => |m| {
                if (m) |mm| detail = mm;
            },
            else => {},
        }
        const note = if (detail.len > 0)
            std.fmt.allocPrint(arena, "the search API (ZODE_BRAVE_KEY) answered HTTP {d}: {s}", .{ res.status, detail }) catch "the search API answered with an error"
        else
            std.fmt.allocPrint(arena, "the search API (ZODE_BRAVE_KEY) answered HTTP {d}", .{res.status}) catch "the search API answered with an error";
        return .{ .fell_back = note };
    }

    return switch (web.braveResults(arena, res.body, max_results)) {
        .results => |r| .{ .done = r },
        // A real index saying "nothing" is a real answer. Falling through to the
        // scrape would trade an authoritative answer for a guess, and reporting
        // it as "the HTML did not match" would send the model off to rephrase a
        // query that was answered fine.
        .empty => .{ .done = std.fmt.allocPrint(
            arena,
            "no results for \"{s}\": the search index (ZODE_BRAVE_KEY) answered with none. That is not \"nothing exists on the internet\" — rephrase the query, or fetch a URL you already know with web_fetch.",
            .{q},
        ) catch "no results; rephrase the query or fetch a URL you know" },
        .unusable => |m| .{ .fell_back = if (m) |mm|
            std.fmt.allocPrint(arena, "the search API (ZODE_BRAVE_KEY) answered with something this build cannot read: {s}", .{mm}) catch "the search API answered with something unreadable"
        else
            "the search API (ZODE_BRAVE_KEY) answered with something this build cannot read (not JSON, or a shape it does not know)" },
    };
}

/// Brave's headers: the token, JSON, and the same `identity` encoding everything
/// here asks for (std does not decompress; see `browserHeaders`).
pub fn braveHeaders(key: []const u8) [4]http.Http.ExtraHeader {
    return .{
        .{ .name = "user-agent", .value = web.user_agent },
        .{ .name = "accept", .value = "application/json" },
        .{ .name = "accept-encoding", .value = "identity" },
        .{ .name = "x-subscription-token", .value = key },
    };
}

/// The Brave failure, in front of whatever the free chain produced (its results
/// or its own failure), so "search worked while silently ignoring my key" cannot
/// happen. It is only ever non-empty while a configured key is being bypassed —
/// exactly while the user needs to see it, and never once the key works.
fn withNote(arena: std.mem.Allocator, note: []const u8, body: []const u8) []const u8 {
    if (note.len == 0) return body;
    return std.fmt.allocPrint(arena, "[search note: {s}]\n\n{s}", .{ note, body }) catch body;
}

/// One engine attempt of the free chain, and everything it can say.
const Stage = struct {
    /// The numbered list. Non-empty means the search is over.
    results: []const u8 = "",
    /// The HTTP status when the engine refused (not 2xx). First one wins.
    refusal: ?u16 = null,
    /// The status when the refusal was a RATE LIMIT (202/429) — the one kind
    /// that is worth naming apart, because it says "wait", not "rephrase".
    limited: ?u16 = null,
    /// A 2xx whose HTML we could not parse: the engines answered and OUR
    /// scraper does not know their page. This is the one case that is our bug.
    bad_layout: bool = false,
    /// The request itself failed (DNS, refused, timeout).
    net_error: bool = false,
};

/// GET `url` and interpret it through `parse`, once. The three engines differ
/// in exactly those five facts and share everything else, so the facts are
/// collected here instead of being re-derived at three call sites with three
/// slightly different conditions.
fn ask(
    h: *http.Http,
    arena: std.mem.Allocator,
    url: []const u8,
    parse: *const fn (std.mem.Allocator, []const u8, usize) []const u8,
    max_results: usize,
) Stage {
    var st = Stage{};
    const res = h.getWithHeaders(url, &browserHeaders()) catch {
        st.net_error = true;
        return st;
    };
    // Parsed results live in the arena, so the body is free to go now — before
    // the next request of the chain reuses this one's buffers.
    defer h.freeBody(res.body);
    if (res.status == 202 or res.status == 429) {
        st.limited = res.status;
        st.refusal = res.status;
        return st;
    }
    if (res.status < 200 or res.status >= 300) {
        st.refusal = res.status;
        return st;
    }
    // Parse ONCE: the old `if (parse(…).len > 0) return parse(…)` walked the
    // same page twice to produce one list.
    const found = parse(arena, res.body, max_results);
    if (found.len > 0)
        st.results = found
    else
        st.bad_layout = true;
    return st;
}

/// The free chain: DuckDuckGo's `html/` and `lite/`, then Bing. No key required.
///
/// The order and the skip are MEASUREMENTS, not preferences (2026-10-08, one
/// machine): `html/` answered 200 on the first request and 202 from the second
/// on; `lite/` shares that bucket and answered 202 at the same moment (so after
/// a rate limit it is SKIPPED: a guaranteed second refusal costing 1.1 s — it is
/// still asked after a 200-with-an-unknown-layout, where the other page of the
/// same engine IS the right next ask); Bing answered 200 in 0.76 s through the
/// whole DDG window, which is why it is the third engine and not decoration.
///
/// Before, a 202 from `html/` ENDED the search — the failure this whole chain
/// exists to avoid happened on the one error it was built for.
fn freeChain(io: std.Io, arena: std.mem.Allocator, q: []const u8, max_results: usize) []const u8 {
    var h = http.Http.init(arena, io);
    defer h.deinit();

    // DDG's `html/`: asks for neither JS nor a key. The query is percent-encoded
    // by hand (`std.Uri.Writer` is not `pub` in 0.16) — and by hand people
    // forget the `&` and the `+`, and the search reaches the server in pieces.
    var url_buf: [1024]u8 = undefined;
    var uw: std.Io.Writer = .fixed(&url_buf);
    uw.writeAll("https://html.duckduckgo.com/html/?q=") catch return "error: query too long";
    percentEncodeQuery(q, &uw) catch return "error: query too long";

    var url2_buf: [1024]u8 = undefined;
    var lite_w: std.Io.Writer = .fixed(&url2_buf);
    lite_w.writeAll("https://lite.duckduckgo.com/lite/?q=") catch return "error: query too long";
    percentEncodeQuery(q, &lite_w) catch return "error: query too long";

    var url3_buf: [1024]u8 = undefined;
    var bing_w: std.Io.Writer = .fixed(&url3_buf);
    bing_w.writeAll("https://www.bing.com/search?q=") catch return "error: query too long";
    percentEncodeQuery(q, &bing_w) catch return "error: query too long";

    var st = ask(&h, arena, uw.buffered(), web.searchResults, max_results);
    if (st.results.len > 0) return st.results;
    var limited = st.limited;
    var refusal = st.refusal;
    var stale = st.bad_layout;
    var all_unreachable = st.net_error;

    // A rate-limited `html/` SKIPS `lite/`: measured, same bucket (see above).
    if (st.limited == null) {
        st = ask(&h, arena, lite_w.buffered(), web.liteSearchResults, max_results);
        if (st.results.len > 0) return st.results;
        if (limited == null) limited = st.limited;
        if (refusal == null) refusal = st.refusal;
        stale = stale or st.bad_layout;
        all_unreachable = all_unreachable and st.net_error;
    }

    st = ask(&h, arena, bing_w.buffered(), web.bingResults, max_results);
    if (st.results.len > 0) return st.results;
    if (limited == null) limited = st.limited;
    if (refusal == null) refusal = st.refusal;
    stale = stale or st.bad_layout;
    all_unreachable = all_unreachable and st.net_error;

    // Nothing answered. The three ways that happens, in the order of what the
    // reader should DO about it:
    //
    // 1. A 200 we could not parse is OUR scraper — the message has to say
    //    "rephrase" would be useless, because the query was answered fine.
    // 2. A rate limit says WAIT, and the test for a live scrape keys on this
    //    message to skip instead of going red for a reason outside the code.
    // 3. Any other refusal is the engine's problem.
    if (stale) return searchFailed(arena, q);
    if (limited) |s| return engineRefused(arena, q, s);
    if (refusal) |s| return engineRefused(arena, q, s);
    if (all_unreachable) {
        return std.fmt.allocPrint(
            arena,
            "error searching \"{s}\": none of the search engines could be reached (network). Check the connection and try again.",
            .{q},
        ) catch "error: no search engine could be reached";
    }
    return searchFailed(arena, q);
}

pub fn browserHeaders() [3]http.Http.ExtraHeader {
    return .{
        .{ .name = "user-agent", .value = web.user_agent },
        .{ .name = "accept", .value = "text/html,application/json,text/plain;q=0.9,*/*;q=0.8" },
        // CAREFUL: you cannot leave `accept-encoding` out and trust things. `std.http`
        // sets `accept_encoding = .omit` (meaning "don't send the header"), and without
        // it GitHub and friends reply gzip: the model eats 16 KB of unreadable bytes
        // and has no idea what the page says. We ask for `identity`
        // explicitly, which is the only way to say "uncompressed" with
        // std, which does not decompress transparently.
        .{ .name = "accept-encoding", .value = "identity" },
    };
}

/// Did the body come compressed? (zstd, gzip, brotli…)
///
/// Safety net for when a server ignores `accept-encoding: identity`:
/// a message saying "it came compressed" is infinitely better than 16 KB of
/// binary that the model reads as text.
pub fn looksCompressed(body: []const u8) ?[]const u8 {
    if (body.len < 2) return null;
    // gzip 1f 8b, zstd 28 b5 2f fd, brotli (no fixed magic: many sites serve it
    // without a recognizable header, and it is detected by invalid UTF-8 below).
    if (body[0] == 0x1f and body[1] == 0x8b) return "gzip";
    if (body[0] == 0x28 and body[1] == 0xb5 and body.len >= 4 and body[2] == 0x2f and body[3] == 0xfd) return "zstd";
    // Generic binary: many NULs or stray control bytes.
    var ctrl: usize = 0;
    const probe = body[0..@min(body.len, 512)];
    for (probe) |b| {
        if (b < 0x09 or (b > 0x0d and b < 0x20)) ctrl += 1;
    }
    if (probe.len > 32 and ctrl * 4 > probe.len) return "binary";
    return null;
}

/// What the model is told when neither endpoint could be parsed.
///
/// It says what happened AND what to do, because "no results parsed" reads as
/// "nothing exists on the internet about this", and the model then tells the user
/// that.
/// The search ENGINE refused the request, which is not our bug and not the
/// model's fault either.
///
/// DuckDuckGo answers HTTP 202 with a full HTML page (an anomaly-detection
/// challenge, measured on 2026-10-04 with four consecutive requests from one
/// machine), so "the endpoint sent nothing parseable" and "the endpoint sent a
/// captcha" arrive at the parser as the same unreadable HTML. Saying "the HTML
/// did not match what this build knows how to read" there sends the model off to
/// rephrase a query that was perfectly fine, and it is what made the live test
/// flaky instead of skipped.
pub fn engineRefused(arena: std.mem.Allocator, q: []const u8, status: u16) []const u8 {
    return switch (status) {
        // 202 is what DuckDuckGo uses to throttle; it arrives as a captcha page.
        202, 429 => std.fmt.allocPrint(
            arena,
            "the search engine is refusing requests from this machine right now (HTTP {d} for \"{s}\"). That is rate limiting, not a bad query: do NOT rephrase it and do NOT retry in a loop. Wait, or answer from what you already have, or fetch a URL you already know with web_fetch.",
            .{ status, q },
        ) catch "the search engine is rate limiting this machine",
        else => std.fmt.allocPrint(
            arena,
            "the search engine answered HTTP {d} for \"{s}\". That is a problem on their side, not a bad query, and not something to rephrase.",
            .{ status, q },
        ) catch "the search engine returned an error",
    };
}

pub fn searchFailed(arena: std.mem.Allocator, q: []const u8) []const u8 {
    return std.fmt.allocPrint(
        arena,
        "no results could be parsed for \"{s}\". The search engines answered, but their HTML did not match what this build knows how to read. Do NOT read that as \"there is nothing about this\": rephrase the query, or fetch a URL you already know with web_fetch.",
        .{q},
    ) catch "the search could not be read; rephrase the query or fetch a URL you know";
}

/// Percent-encoding of a query string, by hand.
///
/// `std.Uri.Writer` (which does know how) is not `pub` in 0.16, and `std.Uri`
/// only exposes the encoder internally. There are four reserved characters and it is one
/// line; what matters is that `&` and `+` are accounted for: without them, "zod & mcp"
/// reaches the server as two different searches.
pub fn percentEncodeQuery(raw: []const u8, w: *std.Io.Writer) !void {
    for (raw) |c| {
        const safe = std.ascii.isAlphanumeric(c) or c == '-' or c == '_' or c == '.' or c == '~';
        if (safe) {
            try w.writeByte(c);
        } else if (c == ' ') {
            try w.writeByte('+');
        } else {
            try w.print("%{X:0>2}", .{c});
        }
    }
}

/// `ZODE_WEB_ALLOW_LOCAL=1` lets `web_fetch` reach loopback and the private ranges.
///
/// It is one variable and not a `--allow-local` flag because the thing it is for is a
/// standing preference ("I fetch my own dev server from here"), not a per-call decision.
fn allowLocal() bool {
    const v = agent.environ_global orelse return false;
    const s = v.get("ZODE_WEB_ALLOW_LOCAL") orelse return false;
    return s.len > 0 and !std.mem.eql(u8, s, "0") and !std.mem.eql(u8, s, "false");
}

pub fn isHttpUrl(url: []const u8) bool {
    if (std.mem.startsWith(u8, url, "http://")) return true;
    if (std.mem.startsWith(u8, url, "https://")) return true;
    return false;
}

/// Is the body HTML?
///
/// It is deduced from the body and NOT from `content-type`: that header lives in
/// `receiveHead`'s redirect buffer, which dies when the request returns (see the note in
/// `http_client.JsonResult`). A server can also send `text/plain` with
/// HTML inside, or the other way round, so the header was not to be trusted either.
///
/// It looks at the start of the document for `<!doctype html`, `<html`, `<head` or
/// `<body`, which is where any template puts them, and rejects what starts
/// with `{` or `[` (JSON) or with `#!` (a gist's shebang).
pub fn looksLikeHtml(body: []const u8) bool {
    const head = body[0..@min(body.len, 1024)];
    if (head.len == 0) return false;
    if (head[0] == '{' or head[0] == '[') return false;
    const trimmed = std.mem.trimStart(u8, head, " \t\r\n\u{feff}");
    if (std.mem.startsWith(u8, trimmed, "#!")) return false;
    return std.ascii.indexOfIgnoreCase(trimmed, "<!doctype html") != null or
        std.ascii.indexOfIgnoreCase(trimmed, "<html") != null or
        std.ascii.indexOfIgnoreCase(trimmed, "<head") != null or
        std.ascii.indexOfIgnoreCase(trimmed, "<body") != null;
}

/// `true` if the error is a network error (and the test is skipped) instead of a real failure.
pub fn isNetError(err: anyerror) bool {
    return switch (err) {
        error.ConnectionRefused,
        error.ConnectionResetByPeer,
        error.HostLackingDnsResolver,
        error.TemporaryNameServerFailure,
        error.NameServerFailure,
        error.UnknownHostName,
        error.ConnectionTimedOut,
        error.NetworkUnreachable,
        error.SocketNotConnected,
        => true,
        else => false,
    };
}

